1	export type Item = {
2	  type: string;
3	};
4	
5	export type QuoteStep = {
6	  op: "quote";
7	  items: Item[];
8	};
9	
10	export type Scenario = {
11	  customer: { yearsWithMHPCO: number };
12	  steps: QuoteStep[];
13	};
14	
15	export type ScenarioResult = {
16	  results: unknown[];
17	};
18	
19	const PROCESSING_FEE = 5;
20	const FIRST_INSURANCE_SURCHARGE = 0.1;
21	
22	const BASE_PREMIUMS: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	};
27	
28	const sum = (amounts: number[]): number =>
29	  amounts.reduce((total, amount) => total + amount, 0);
30	
31	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
32	
33	const quotePremium = (items: Item[]): number => {
34	  const basePremium = sum(items.map(basePremiumOf));
35	
36	  return (
37	    basePremium + basePremium * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE
38	  );
39	};
40	
41	export const runScenario = (scenario: Scenario): ScenarioResult => ({
42	  results: scenario.steps.map((step) => ({
43	    premium: quotePremium(step.items),
44	  })),
45	});
